INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-004', TRUE, '工学院', '2026-10-21', '关于科研项目经费外拨事项的公示2026-10-21', '奖助学金', NULL, NULL, NULL, NULL, NULL, 0.5, 'medium', '[{"text": "我校联合安徽和粮机械有限公司、安徽宏翔农业机械有限公司和安徽省农业机械技术推广总站成功申报 2024", "quote": "我校联合安徽和粮机械有限公司、安徽宏翔农业机械有限公司和安徽省农业机械技术推广总站成功申报 2024"}]'::jsonb, '奖助学金：关于科研项目经费外拨事项的公示2026-10-21', '[{"text": "我校联合安徽和粮机械有限公司、安徽宏翔农业机械有限公司和安徽省农业机械技术推广总站成功申报 2024", "quote": "我校联合安徽和粮机械有限公司、安徽宏翔农业机械有限公司和安徽省农业机械技术推广总站成功申报 2024"}]'::jsonb, '我校联合安徽和粮机械有限公司、安徽宏翔农业机械有限公司和安徽省农业机械技术推广总站成功申报 2024年度安徽省科技攻坚计划项目（重点项目）“稻麦兼用智能化播种与干燥装备创制及应用”（项目编号：202423l10050007），获批省财政经费150万元。根据 《联合申报项目协议书》和 《科研项目合作协议书》有关条款，项目获得资助后，安徽农业大学、安徽和粮机械有限公司、安徽宏翔农业机械有限公司和安徽省农业机械技术推广总站按获得的省级财政资金的 4:3:2:1比例分配经费，分别为60万元、45万元、30万元和15万元。', 'https://gxy.ahau.edu.cn/info/1143/43831.htm', '工学院 · 通知公告', 'gxy', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at